/**
 * G40-532 — display names for request categories.
 *
 * ⛔ THIS MAPS STORED VALUE -> WHAT A HUMAN READS. IT NEVER CHANGES STORAGE.
 *
 * "Other" is not only a label. The same string is the order's stored
 * `category_type` / `request_type`, the route key and schema filename
 * (`category.toLowerCase().replace(/\s|&/g, "")` -> `other.json`), the
 * service-fee key in the backend's `getServiceFee` switch, and the value a
 * Gopher's saved work preferences are matched on. Renaming the stored value
 * would zero the service fee (it falls through to `default: amount = 0`
 * rather than erroring), dead-end the category route, orphan historical
 * orders, and stop matching jobs to the Gophers who opted into them.
 *
 * So the rename happens here, at the last moment before render, and the wire
 * keeps saying "Other". Owner decision 2026-09-23 (G40-532): display-only.
 *
 * Sub-categories that merely CONTAIN the word — "CBD/Other", "Other Home
 * Project", the Moving sub-type captioned "Other" — are different categories
 * and are deliberately absent from this map. "Other Yard Project(s)" is a
 * Yard Project sub-type: under the owner's 2026-09-30 ruling ("All subs of
 * Yard Project are now Yard Project") it reads "Yard Project" (see
 * requestTitleLabel below), and it is still never "Custom Task".
 */
const CATEGORY_DISPLAY_NAMES = {
  Other: "Custom Task",
};

/**
 * @param {string} storedCategory the raw `category_type` off an order.
 * @returns {string} what to show a human. Unknown or empty values pass
 *   through unchanged, so a category added later reads as itself rather than
 *   rendering blank.
 */
export function categoryLabel(storedCategory) {
  if (!storedCategory) return storedCategory;
  return CATEGORY_DISPLAY_NAMES[storedCategory] || storedCategory;
}

/**
 * The display name for the category stored as "Other".
 *
 * ⛔ `other.json`'s `header.centerElement.title` MUST equal this string.
 * RequesterCategoryHeader keys off that title to swap in the requester's own
 * typed description, so if the two ever drift the header silently stops
 * showing what the requester wrote and shows the category name instead.
 * Importing it from here is what stops that drift.
 */
export const CUSTOM_TASK_LABEL = CATEGORY_DISPLAY_NAMES.Other;

/* ─── G40-551: request TITLES, as a human reads them ────────────────────────
   Owner, 2026-09-30: "i would like all 'other' jobs to read as 'Custom
   Task'" and "The Main 'Other' category is now called 'Custom Task.' The
   Other Yard Project was just a sub of Yard Project. All subs of Yard
   Project are now Yard Project."

   ⛔ DISPLAY ONLY, same as categoryLabel above. The stored title is built by
   orderObject.js ("Other - <typed>", or the form's hidden "Yard Project -
   <sub>") and is what the server stores, searches and emails; it is never
   passed through these.

   These work from the title string ALONE, because chat and the inbox are
   handed the title and nothing else.

   Both patterns are anchored at both ends, so a title that merely contains
   the word is left alone: "Moving - Other", "Home Services - Other Home
   Project", "Delivery - Age-Restricted" (stored sub "CBD/Other") and
   "Other Home Project" never match. Replacing the WORD would have produced
   "Moving - Custom Task" and "Custom Task Home Project". */
const MAIN_OTHER = /^Other(?:\s*-\s*([\s\S]*))?$/; // "Other" or "Other - <typed>"
const YARD_TITLE = /^Yard Project(?:\s*-[\s\S]*)?$/; // "Yard Project[ - <sub>]"
export const YARD_PROJECT_LABEL = "Yard Project";

/**
 * The requester's own words from a Custom Task's stored title:
 * "Other - Pick-up couch" → "Pick-up couch". Everything after the FIRST
 * "Other -" is kept, hyphens and all ("split('-')[1]" cut it at the next
 * hyphen). "" when the title is not a Custom Task title or has no words.
 */
export const customTaskText = (title) => {
  const m = MAIN_OTHER.exec(typeof title === "string" ? title : "");
  return m ? (m[1] || "").trim() : "";
};

/**
 * G40-573 — the short caption on the requester's home cards for a Custom
 * Task: the typed words (cut at 8 characters, as the cards always did), or
 * "Custom Task" when there are none (the new flow stores "Other - "; John's
 * test request read "| 10.06.26").
 */
export const customTaskCardCaption = (title) => {
  const typed = customTaskText(title);
  if (!typed) return CUSTOM_TASK_LABEL;
  return typed.length > 8 ? `${typed.substring(0, 8)} ...` : typed;
};

/**
 * What a person reads for a request's stored title.
 *   "Other - <typed>"          → "Custom Task - <typed>"
 *   "Other" / "Other - "       → "Custom Task"
 *   "Yard Project - <any sub>" → "Yard Project"
 *   anything else, "" or null  → unchanged
 * Applying it twice changes nothing.
 */
export function requestTitleLabel(title) {
  if (!title || typeof title !== "string") return title;
  const m = MAIN_OTHER.exec(title);
  if (m) {
    const typed = (m[1] || "").trim();
    return typed ? `${CUSTOM_TASK_LABEL} - ${typed}` : CUSTOM_TASK_LABEL;
  }
  return YARD_TITLE.test(title) ? YARD_PROJECT_LABEL : title;
}

/**
 * A Previous Jobs card's type, as the backend's jobTypeLabel sends it
 * ("Other", "Yard Project · Lawn Mowing/Service", "Moving · Other").
 * Only the main "Other" and Yard's sub-types change; "Moving · Other" is
 * Moving's own sub-type and stays.
 */
export const previousJobTypeLabel = (type) => {
  if (type === "Other") return CUSTOM_TASK_LABEL;
  if (typeof type === "string" && /^Yard Project(\s·|$)/.test(type)) {
    return YARD_PROJECT_LABEL;
  }
  return type;
};

export default categoryLabel;
